<?php
require_once '../config/db.php';$q=trim((string)($_GET['q']??''));$status=$_GET['status']??'';$where=[];$params=[];if($q!==''){$where[]="(CONCAT(e.first_name,' ',e.last_name) LIKE ? OR e.employee_number LIKE ? OR e.department LIKE ? OR e.designation LIKE ?)";for($i=0;$i<4;$i++)$params[]='%'.$q.'%';}if(in_array($status,['active','inactive','terminated','on_leave'],true)){$where[]='e.status=?';$params[]=$status;}$sql="SELECT e.*,COUNT(p.id) payslip_count,COALESCE(SUM(CASE WHEN p.status='paid' THEN p.net_payable ELSE 0 END),0) total_paid,MAX(p.month_year) last_pay_period FROM employees e LEFT JOIN payslips p ON p.employee_id=e.id".($where?' WHERE '.implode(' AND ',$where):'').' GROUP BY e.id ORDER BY e.joined_date DESC,e.id DESC';$s=$pdo->prepare($sql);$s->execute($params);$employees=$s->fetchAll();$stats=$pdo->query("SELECT COUNT(*) total,SUM(status='active') active,SUM(status='on_leave') on_leave,COALESCE(SUM(CASE WHEN status='active' THEN base_salary ELSE 0 END),0) payroll FROM employees")->fetch();require_once 'includes/header.php';require_once 'includes/sidebar.php';
?>
<main class="flex-1 h-screen overflow-y-auto app-scroll"><header class="bg-white border-b px-5 md:px-8 py-5 flex justify-between items-center sticky top-0 z-10"><div class="flex items-center gap-4"><button data-sidebar-toggle class="lg:hidden text-2xl">☰</button><div><h2 class="text-2xl font-bold">Employees</h2><p class="text-sm text-slate-500">HR profiles, contacts, employment, and payroll history</p></div></div><a href="add_employee.php" class="brand-bg text-white px-4 py-2.5 rounded-lg font-semibold">+ Add employee</a></header><div class="p-5 md:p-8 max-w-7xl mx-auto"><div class="grid sm:grid-cols-2 xl:grid-cols-4 gap-4 mb-6"><?php foreach([['Employees',$stats['total']],['Active',$stats['active']],['On leave',$stats['on_leave']],['Monthly base payroll',money($pdo,$stats['payroll'])]] as [$l,$v]):?><div class="bg-white border rounded-xl p-5"><p class="text-sm text-slate-500"><?=h($l)?></p><p class="text-2xl font-black mt-1"><?=h((string)$v)?></p></div><?php endforeach;?></div>
<div class="bg-white border rounded-2xl overflow-hidden shadow-sm"><form class="p-4 border-b flex flex-wrap gap-3"><input name="q" value="<?=h($q)?>" placeholder="Search name, ID, department, or role" class="border rounded-lg px-3 py-2 flex-1 min-w-60"><select name="status" class="border rounded-lg px-3 py-2 bg-white"><option value="">All statuses</option><?php foreach(['active'=>'Active','on_leave'=>'On leave','inactive'=>'Inactive','terminated'=>'Terminated'] as $k=>$v):?><option value="<?=$k?>" <?=$status===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select><button class="bg-slate-900 text-white rounded-lg px-5 py-2">Filter</button></form><div class="overflow-x-auto"><table class="w-full text-sm"><thead class="bg-slate-50 text-slate-500"><tr><th class="text-left p-4">Employee</th><th class="text-left p-4">Role</th><th class="text-left p-4">Contact</th><th class="text-right p-4">Base salary</th><th class="text-left p-4">Payroll</th><th class="text-left p-4">Status</th><th class="p-4"></th></tr></thead><tbody class="divide-y"><?php foreach($employees as $e):?><tr class="hover:bg-slate-50"><td class="p-4"><div class="flex items-center gap-3"><div class="w-10 h-10 rounded-full bg-blue-100 text-blue-700 flex items-center justify-center font-bold"><?=h(strtoupper(substr($e['first_name'],0,1).substr($e['last_name'],0,1)))?></div><div><a href="view_employee.php?id=<?=$e['id']?>" class="font-bold brand-text"><?=h($e['first_name'].' '.$e['last_name'])?></a><p class="text-xs text-slate-400"><?=h($e['employee_number']?:'No employee ID')?> · Joined <?=h(date('M Y',strtotime($e['joined_date'])))?></p></div></div></td><td class="p-4"><strong><?=h($e['designation'])?></strong><p class="text-xs text-slate-500"><?=h($e['department']?:'No department')?></p></td><td class="p-4"><?=h($e['email']?:$e['personal_email']?:'—')?><p class="text-xs text-slate-500"><?=h($e['phone']?:'—')?></p></td><td class="p-4 text-right font-bold money"><?=money($pdo,$e['base_salary'])?></td><td class="p-4"><?=h((string)$e['payslip_count'])?> payslips<p class="text-xs text-slate-500"><?=money($pdo,$e['total_paid'])?> paid</p></td><td class="p-4"><span class="px-2.5 py-1 rounded-full text-xs font-bold bg-slate-100"><?=h(ucwords(str_replace('_',' ',$e['status'])))?></span></td><td class="p-4 text-right"><a href="view_employee.php?id=<?=$e['id']?>" class="brand-text font-semibold">Profile →</a></td></tr><?php endforeach;?><?php if(!$employees):?><tr><td colspan="7" class="p-12 text-center text-slate-500">No employees match this view.</td></tr><?php endif;?></tbody></table></div></div></div></main><?php require_once 'includes/footer.php';?>
